pragma solidity ^0.8.20;
contract BaseRegistry { uint256 public count; function record(uint256 value) public virtual { count += value; } }
contract RewardRegistry is BaseRegistry { uint256 public bonus; function record(uint256 value) public override { super.record(value); bonus += value / 10; } }

